-- Refka v1: every migration in one file, for the Supabase SQL editor on a fresh project.
-- GENERATED by supabase/build-deploy.sh from supabase/migrations/. Do not edit by hand.
-- Safe to run again: tables use "if not exists", functions "create or replace", grants are re-applied.
-- Needs only what Supabase provides: auth.users, auth.uid(), auth.jwt(), roles anon/authenticated,
-- and pgcrypto in schema extensions (created below if missing).

begin;

-- ==================================================================== 0001_schema.sql
-- Refka v1 schema. Runs unchanged on Supabase (Postgres 15+) and on local Postgres 16 after tests/local_prelude.sql.
-- Re-runnable: tables and indexes use "if not exists" (a re-run never changes an existing table; write a new
-- migration for that).
-- Rule: the front end never touches tables. RLS is enabled on every table with NO policies and all table
-- privileges are revoked from anon and authenticated. Every read and write goes through a function in 0002.

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

-- ---------------------------------------------------------------- gyms
create table if not exists public.gyms (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique
              check (slug ~ '^[a-z0-9]([a-z0-9-]{1,28})[a-z0-9]$' and slug !~ '--'),
  name        text not null check (char_length(name) between 2 and 60),
  name_ar     text check (name_ar is null or char_length(name_ar) <= 60),
  country     text not null default 'EG',
  currency    text not null default 'EGP',
  brand       jsonb not null default '{}'::jsonb,
  settings    jsonb not null default '{"cross": true, "posts": "all"}'::jsonb,
  pay         jsonb not null default '{"cash": false}'::jsonb,
  status      text not null default 'draft' check (status in ('draft','live')),
  owner_id    uuid not null references auth.users(id) on delete restrict,
  qr_secret   text not null default encode(extensions.gen_random_bytes(32), 'hex'),
  created_at  timestamptz not null default now()
);
create unique index if not exists gyms_owner_uq on public.gyms(owner_id);   -- one gym per owner in v1

create table if not exists public.gym_staff (
  gym_id  uuid not null references public.gyms(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role    text not null default 'owner' check (role in ('owner')),
  name    text,
  primary key (gym_id, user_id)
);

-- ---------------------------------------------------------------- packages
create table if not exists public.packages (
  id           uuid primary key default gen_random_uuid(),
  gym_id       uuid not null references public.gyms(id) on delete cascade,
  name         text not null check (char_length(name) between 1 and 60),
  name_ar      text check (name_ar is null or char_length(name_ar) <= 60),
  months       int  not null check (months between 1 and 36),
  price        int  not null check (price > 0 and price <= 10000000),
  before_price int  check (before_price is null or before_price > price),
  until        date,
  active       boolean not null default true,
  sort         int not null default 0,
  deleted_at   timestamptz,                      -- soft delete so old memberships and payments keep their package
  created_at   timestamptz not null default now(),
  check (before_price is null or until is not null)
);
create index if not exists packages_gym_ix on public.packages(gym_id, sort);

-- ---------------------------------------------------------------- memberships
create table if not exists public.memberships (
  id         uuid primary key default gen_random_uuid(),
  gym_id     uuid not null references public.gyms(id) on delete cascade,
  phone      text not null check (phone ~ '^\+[0-9]{10,15}$'),
  name       text not null check (char_length(name) between 2 and 60),
  gender     text check (gender in ('m','f')),
  package_id uuid references public.packages(id) on delete set null,
  starts     date,
  ends       date,
  user_id    uuid references auth.users(id) on delete set null,
  status     text not null default 'listed' check (status in ('listed','active','guest')),
  qr_used_bucket bigint,                         -- replay protection for the rotating QR
  qr_used_at     timestamptz,
  created_at timestamptz not null default now(),
  unique (gym_id, phone),
  check (status = 'listed' or user_id is not null),
  check (status <> 'listed' or user_id is null)
);
create unique index if not exists memberships_gym_user_uq on public.memberships(gym_id, user_id) where user_id is not null;
create index if not exists memberships_user_ix on public.memberships(user_id) where user_id is not null;

-- ---------------------------------------------------------------- profiles
create table if not exists public.profiles (
  user_id    uuid primary key references auth.users(id) on delete cascade,
  phone      text not null unique check (phone ~ '^\+[0-9]{10,15}$'),
  name       text not null check (char_length(name) between 2 and 60),
  gender     text not null check (gender in ('m','f')),
  birth_year int  not null check (birth_year between 1900 and 2100),
  bio        text check (bio is null or char_length(bio) <= 300),
  goal       text check (goal is null or char_length(goal) <= 40),
  level      text check (level is null or char_length(level) <= 40),
  times      text[] not null default '{}',
  vis        text not null check (vis in ('all','gender','none')),
  avatar     text check (avatar is null or char_length(avatar) <= 56000),
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------- payments
create table if not exists public.payments (
  id            uuid primary key default gen_random_uuid(),
  gym_id        uuid not null references public.gyms(id) on delete cascade,
  membership_id uuid not null references public.memberships(id) on delete cascade,
  package_id    uuid references public.packages(id) on delete set null,
  amount        int not null check (amount > 0),
  method        text not null check (method in ('instapay','wallet','cash')),
  ref           text check (ref is null or char_length(ref) <= 60),
  status        text not null default 'pending' check (status in ('pending','ok','rejected')),
  created_at    timestamptz not null default now(),
  decided_by    uuid references auth.users(id) on delete set null,
  decided_at    timestamptz
);
create unique index if not exists payments_one_pending_uq on public.payments(membership_id) where status = 'pending';
create index if not exists payments_gym_ix on public.payments(gym_id, status, created_at);

-- ---------------------------------------------------------------- checkins
create table if not exists public.checkins (
  id            uuid primary key default gen_random_uuid(),
  gym_id        uuid not null references public.gyms(id) on delete cascade,
  membership_id uuid not null references public.memberships(id) on delete cascade,
  at            timestamptz not null default now(),
  via           text not null check (via in ('qr','desk'))
);
create index if not exists checkins_gym_at_ix on public.checkins(gym_id, at desc);
create index if not exists checkins_membership_ix on public.checkins(membership_id, at desc);

-- ---------------------------------------------------------------- requests
create table if not exists public.requests (
  id         uuid primary key default gen_random_uuid(),
  gym_id     uuid not null references public.gyms(id) on delete cascade,
  from_user  uuid not null references auth.users(id) on delete cascade,
  to_user    uuid not null references auth.users(id) on delete cascade,
  kind       text not null check (kind in ('train','spot')),
  slot       text check (slot is null or char_length(slot) <= 40),
  status     text not null default 'pending' check (status in ('pending','accepted','declined','cancelled')),
  created_at timestamptz not null default now(),
  decided_at timestamptz,
  check (from_user <> to_user)
);
create unique index if not exists requests_one_pending_uq on public.requests(gym_id, from_user, to_user) where status = 'pending';
create index if not exists requests_to_ix on public.requests(to_user, gym_id, status);
create index if not exists requests_from_ix on public.requests(from_user, created_at desc);

-- ---------------------------------------------------------------- refkas
create table if not exists public.refkas (
  id        uuid primary key default gen_random_uuid(),
  gym_id    uuid not null references public.gyms(id) on delete cascade,
  a         uuid not null references auth.users(id) on delete cascade,
  b         uuid not null references auth.users(id) on delete cascade,
  since     timestamptz not null default now(),
  ended_at  timestamptz,
  a_read_at timestamptz,                         -- read markers for unread counts
  b_read_at timestamptz,
  check (a < b)
);
create unique index if not exists refkas_one_open_uq on public.refkas(gym_id, a, b) where ended_at is null;
create index if not exists refkas_a_ix on public.refkas(a);
create index if not exists refkas_b_ix on public.refkas(b);

create table if not exists public.messages (
  id        uuid primary key default gen_random_uuid(),
  refka_id  uuid not null references public.refkas(id) on delete cascade,
  from_user uuid not null references auth.users(id) on delete cascade,
  body      text not null check (char_length(body) between 1 and 1000),
  at        timestamptz not null default now()
);
create index if not exists messages_refka_ix on public.messages(refka_id, at);
create index if not exists messages_from_ix on public.messages(from_user, at desc);

-- ---------------------------------------------------------------- blocks, posts, reports
create table if not exists public.blocks (
  blocker uuid not null references auth.users(id) on delete cascade,
  blocked uuid not null references auth.users(id) on delete cascade,
  at      timestamptz not null default now(),
  primary key (blocker, blocked),
  check (blocker <> blocked)
);
create index if not exists blocks_blocked_ix on public.blocks(blocked);

create table if not exists public.posts (
  id      uuid primary key default gen_random_uuid(),
  gym_id  uuid not null references public.gyms(id) on delete cascade,
  by_user uuid not null references auth.users(id) on delete cascade,
  body    text not null check (char_length(body) <= 500),
  img     text check (img is null or char_length(img) <= 205000),
  status  text not null default 'live' check (status in ('live','pending','hidden')),
  at      timestamptz not null default now(),
  check (char_length(body) >= 1 or img is not null)
);
create index if not exists posts_gym_at_ix on public.posts(gym_id, at desc);
create index if not exists posts_by_ix on public.posts(by_user, at desc);

create table if not exists public.post_respects (
  post_id uuid not null references public.posts(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  at      timestamptz not null default now(),
  primary key (post_id, user_id)
);

create table if not exists public.reports (
  id         uuid primary key default gen_random_uuid(),
  gym_id     uuid not null references public.gyms(id) on delete cascade,
  by_user    uuid not null references auth.users(id) on delete cascade,
  about_user uuid references auth.users(id) on delete set null,
  about_post uuid references public.posts(id) on delete set null,
  reason     text not null check (char_length(reason) between 1 and 500),
  status     text not null default 'open' check (status in ('open','done')),
  at         timestamptz not null default now()
);
create index if not exists reports_gym_ix on public.reports(gym_id, status, at);

-- ---------------------------------------------------------------- lock everything down
do $$
declare t text;
begin
  foreach t in array array['gyms','gym_staff','packages','memberships','profiles','payments','checkins',
                           'requests','refkas','messages','blocks','posts','post_respects','reports']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
  end loop;
end $$;

-- ==================================================================== 0002_functions.sql
-- Refka v1 functions, part 1: internal helpers, the visibility rule, public and owner RPCs.
-- Every function: security definer, search_path = public, extensions, pg_temp (pg_temp last, so a caller's
-- temporary table can never shadow a public table inside a definer function), returns jsonb (RPCs), raises a short code.
-- Internal helpers are prefixed rf_ and are NOT executable by anon or authenticated (see 0004_grants.sql).

-- ================================================================ small helpers

create or replace function public.rf_today() returns date
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select (now() at time zone 'Africa/Cairo')::date
$$;

create or replace function public.rf_day_start() returns timestamptz
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select (public.rf_today()::timestamp) at time zone 'Africa/Cairo'
$$;

create or replace function public.rf_uid() returns uuid
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v uuid;
begin
  v := auth.uid();
  if v is null then raise exception 'not_auth'; end if;
  return v;
end $$;

-- same normalisation as app/lib/api.js phoneDigits(): digits only, 00 prefix dropped, 01xxxxxxxxx -> 201xxxxxxxxx
create or replace function public.rf_phone(p text) returns text
language plpgsql immutable security definer set search_path = public, extensions, pg_temp as $$
declare d text;
begin
  if p is null or char_length(p) > 40 then return null; end if;
  d := regexp_replace(p, '[^0-9]', '', 'g');
  if d like '00%' then d := substr(d, 3); end if;
  if d ~ '^01[0-9]{9}$' then d := '2' || d; end if;
  if d !~ '^[0-9]{10,15}$' then return null; end if;
  return '+' || d;
end $$;

-- The caller's phone. Once a profile exists its phone is final. Before that it is derived from the
-- synthetic login email p<digits>@m.refka.tech (unique in auth), never from user_metadata, because
-- user_metadata can be edited by the user himself (see Deviations in CONTRACT.md).
create or replace function public.my_phone() returns text
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; v_phone text; v_email text;
begin
  v_uid := auth.uid();
  if v_uid is null then return null; end if;
  select phone into v_phone from profiles where user_id = v_uid;
  if v_phone is not null then return v_phone; end if;
  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if v_email ~ '^p[0-9]{10,15}@m\.refka\.tech$' then
    return '+' || substr(v_email, 2, position('@' in v_email) - 2);
  end if;
  return null;
end $$;

create or replace function public.rf_int(p text) returns int
language plpgsql immutable security definer set search_path = public, extensions, pg_temp as $$
begin
  if p is null then return null; end if;
  return p::int;
exception when others then raise exception 'bad_input';
end $$;

create or replace function public.rf_date(p text) returns date
language plpgsql immutable security definer set search_path = public, extensions, pg_temp as $$
begin
  if p is null or btrim(p) = '' then return null; end if;
  if p !~ '^\s*[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}' then raise exception 'bad_input'; end if;
  return substr(btrim(p), 1, 10)::date;
exception when others then raise exception 'bad_input';
end $$;

create or replace function public.rf_uuid(p text) returns uuid
language plpgsql immutable security definer set search_path = public, extensions, pg_temp as $$
begin
  if p is null or btrim(p) = '' then return null; end if;
  return p::uuid;
exception when others then raise exception 'bad_input';
end $$;

-- one line text: trimmed, inner whitespace collapsed
create or replace function public.rf_line(p text) returns text
language sql immutable security definer set search_path = public, extensions, pg_temp as $$
  select nullif(btrim(regexp_replace(coalesce(p, ''), '\s+', ' ', 'g')), '')
$$;

create or replace function public.rf_gender(p text) returns text
language sql immutable security definer set search_path = public, extensions, pg_temp as $$
  select case
    when lower(btrim(coalesce(p, ''))) in ('m', 'male', 'man', 'ذكر', 'راجل', 'رجل') then 'm'
    when lower(btrim(coalesce(p, ''))) in ('f', 'female', 'woman', 'أنثى', 'انثى', 'انثي', 'أنثي', 'ست', 'بنت') then 'f'
    else null end
$$;

-- raster data URL only (no svg: it can carry script), with a length cap on the whole string
create or replace function public.rf_img_ok(p text, p_max int) returns boolean
language sql immutable security definer set search_path = public, extensions, pg_temp as $$
  select p is not null and char_length(p) <= p_max
     and p ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$'
$$;

create or replace function public.rf_reserved_slug(p text) returns boolean
language sql immutable security definer set search_path = public, extensions, pg_temp as $$
  select p = any (array[
    'app','admin','api','www','pay','ar','en','de','owner','owners','login','logout','signup','signin','register',
    'auth','rest','rpc','m','member','members','gym','gyms','refka','refqa','rifqa','support','help','about','blog',
    'assets','static','dev','test','staging','mail','dashboard','console','settings','account','billing','pricing',
    'terms','privacy','legal','security','status','docs','null','undefined','root','system','supabase','index',
    'home','join','new','public','private','demo'])
$$;

-- ================================================================ lookups

create or replace function public.rf_owner_gym() returns public.gyms
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; g gyms;
begin
  v_uid := rf_uid();
  select * into g from gyms where owner_id = v_uid;
  if not found then raise exception 'not_owner'; end if;
  return g;
end $$;

-- p_gym arguments accept the gym id or its slug
create or replace function public.rf_gym(p text) returns public.gyms
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  if p is null or char_length(p) > 64 then raise exception 'not_found'; end if;
  if p ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    select * into g from gyms where id = p::uuid;
  else
    select * into g from gyms where slug = lower(btrim(p));
  end if;
  if not found then raise exception 'not_found'; end if;
  return g;
end $$;

-- "active membership" of the visibility rule: linked, status active, not expired for more than 7 days
create or replace function public.rf_active(m public.memberships) returns boolean
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select m.id is not null and m.user_id is not null and m.status = 'active'
     and (m.ends is null or m.ends >= public.rf_today() - 7)
$$;

-- the caller's active membership in a gym, or not_member. Used by every social member function.
create or replace function public.rf_member(p_gym text) returns public.memberships
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; g gyms; m memberships;
begin
  v_uid := rf_uid();
  g := rf_gym(p_gym);
  select * into m from memberships where gym_id = g.id and user_id = v_uid;
  if not found or not rf_active(m) then raise exception 'not_member'; end if;
  return m;
end $$;

-- ================================================================ THE visibility rule
-- can_see(viewer, target, gym): may viewer see target inside this gym?
-- p_known = true is the relaxed form for an existing refka: a target who later chose vis='none' stays
-- visible to his existing partners, but blocks, membership, the minors rule and the gender rule still hold
-- (cross gender then needs: gym.cross on and neither side has vis='gender').
create or replace function public.can_see(viewer uuid, target uuid, gym uuid, p_known boolean default false)
returns boolean
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare
  pv profiles; pt profiles; mv memberships; mt memberships;
  v_settings jsonb; v_year int; gv text; gt text;
begin
  if viewer is null or target is null or gym is null then return false; end if;
  if viewer = target then return true; end if;
  if exists (select 1 from blocks b
             where (b.blocker = viewer and b.blocked = target) or (b.blocker = target and b.blocked = viewer)) then
    return false;
  end if;
  select * into pv from profiles where user_id = viewer;
  if not found then return false; end if;
  select * into pt from profiles where user_id = target;
  if not found then return false; end if;
  if pt.vis = 'none' and not coalesce(p_known, false) then return false; end if;
  select * into mv from memberships where gym_id = gym and user_id = viewer;
  if not found or not rf_active(mv) then return false; end if;
  select * into mt from memberships where gym_id = gym and user_id = target;
  if not found or not rf_active(mt) then return false; end if;
  v_year := extract(year from rf_today())::int;
  if ((v_year - pv.birth_year) < 18) <> ((v_year - pt.birth_year) < 18) then return false; end if;
  -- the gym's record of gender wins over the self declared one
  gv := coalesce(mv.gender, pv.gender);
  gt := coalesce(mt.gender, pt.gender);
  if gv = gt then return true; end if;
  select settings into v_settings from gyms where id = gym;
  if not coalesce((v_settings ->> 'cross') = 'true', false) then return false; end if;
  if coalesce(p_known, false) then
    return pv.vis <> 'gender' and pt.vis <> 'gender';
  end if;
  return pv.vis = 'all' and pt.vis = 'all';
end $$;

-- both directions: used wherever two people interact (requests, chat)
create or replace function public.rf_mutual(p_a uuid, p_b uuid, p_gym uuid, p_known boolean default false)
returns boolean
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select public.can_see(p_a, p_b, p_gym, p_known) and public.can_see(p_b, p_a, p_gym, p_known)
$$;

-- ================================================================ json builders (never include qr_secret)

create or replace function public.rf_gym_json(g public.gyms) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', g.id, 'slug', g.slug, 'name', g.name, 'name_ar', g.name_ar,
    'country', g.country, 'currency', g.currency, 'brand', g.brand, 'settings', g.settings, 'pay', g.pay,
    'status', g.status, 'created_at', g.created_at)
$$;

create or replace function public.rf_gym_brief(g public.gyms) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', g.id, 'slug', g.slug, 'name', g.name, 'name_ar', g.name_ar, 'brand', g.brand)
$$;

-- owner view of a package: raw values
create or replace function public.rf_pkg_json(p public.packages) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'name', p.name, 'name_ar', p.name_ar, 'months', p.months, 'price', p.price,
    'before_price', p.before_price, 'until', p.until, 'active', p.active, 'sort', p.sort)
$$;

-- price a member pays today: the offer price while the offer runs, the before_price once "until" has passed
create or replace function public.rf_pkg_price(p public.packages) returns int
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select case when p.before_price is not null and p.until is not null and p.until < public.rf_today()
              then p.before_price else p.price end
$$;

-- member/public view of a package: effective price, offer fields only while the offer runs
create or replace function public.rf_pkg_public(p public.packages) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'name', p.name, 'name_ar', p.name_ar, 'months', p.months,
    'price', public.rf_pkg_price(p),
    'before_price', case when p.until is not null and p.until >= public.rf_today() then p.before_price end,
    'until', case when p.before_price is not null and p.until >= public.rf_today() then p.until end)
$$;

create or replace function public.rf_pkg_brief(p_id uuid) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select (select jsonb_build_object('id', p.id, 'name', p.name, 'name_ar', p.name_ar, 'months', p.months)
          from public.packages p where p.id = p_id)
$$;

create or replace function public.rf_packages_public(p_gym uuid) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select coalesce(jsonb_agg(public.rf_pkg_public(p) order by p.sort, p.price, p.created_at), '[]'::jsonb)
  from public.packages p where p.gym_id = p_gym and p.active and p.deleted_at is null
$$;

-- own profile (the only place a phone is returned to a member, and it is his own)
create or replace function public.rf_profile_json(p public.profiles) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('user_id', p.user_id, 'phone', p.phone, 'name', p.name, 'gender', p.gender,
    'birth_year', p.birth_year, 'bio', p.bio, 'goal', p.goal, 'level', p.level, 'times', to_jsonb(p.times),
    'vis', p.vis, 'avatar', p.avatar, 'created_at', p.created_at)
$$;

-- what one member may learn about another: never the phone, never the birth year
create or replace function public.rf_person(p_user uuid, p_goal boolean default false) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select (select case when p_goal
            then jsonb_build_object('user_id', p.user_id, 'name', p.name, 'avatar', p.avatar, 'goal', p.goal)
            else jsonb_build_object('user_id', p.user_id, 'name', p.name, 'avatar', p.avatar) end
          from public.profiles p where p.user_id = p_user)
$$;

create or replace function public.rf_membership_json(m public.memberships) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', m.id,
    'gym', (select public.rf_gym_brief(g) from public.gyms g where g.id = m.gym_id),
    'status', m.status, 'package', public.rf_pkg_brief(m.package_id), 'starts', m.starts, 'ends', m.ends,
    'days_left', case when m.ends is null then null else m.ends - public.rf_today() end)
$$;

create or replace function public.rf_post_json(p public.posts, p_viewer uuid) returns jsonb
language sql stable security definer set search_path = public, extensions, pg_temp as $$
  select jsonb_build_object('id', p.id, 'body', p.body, 'img', p.img, 'at', p.at, 'status', p.status,
    'mine', p.by_user = p_viewer,
    'by', public.rf_person(p.by_user),
    'respects', case when p.by_user = p_viewer
                     then (select count(*) from public.post_respects r where r.post_id = p.id) end,
    'respected', exists (select 1 from public.post_respects r where r.post_id = p.id and r.user_id = p_viewer))
$$;

-- rotating member QR: rf1.<membership id>.<60 s bucket>.<first 32 hex of HMAC-SHA256(id.bucket, gym secret)>
create or replace function public.rf_qr_sig(p_secret text, p_membership uuid, p_bucket bigint) returns text
language sql immutable security definer set search_path = public, extensions, pg_temp as $$
  select substr(encode(hmac(p_membership::text || '.' || p_bucket::text, p_secret, 'sha256'), 'hex'), 1, 32)
$$;

create or replace function public.rf_qr_token(p_secret text, p_membership uuid, p_bucket bigint) returns text
language sql immutable security definer set search_path = public, extensions, pg_temp as $$
  select 'rf1.' || p_membership::text || '.' || p_bucket::text || '.' || public.rf_qr_sig(p_secret, p_membership, p_bucket)
$$;

-- a live gym must always keep one active package and one pay method
create or replace function public.rf_check_live(p_gym uuid) returns void
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  select * into g from gyms where id = p_gym;
  if not exists (select 1 from packages where gym_id = g.id and active and deleted_at is null) then
    raise exception 'need_package';
  end if;
  if not (coalesce((g.pay ->> 'cash') = 'true', false)
          or coalesce(btrim(g.pay ->> 'instapay'), '') <> ''
          or coalesce(btrim(g.pay ->> 'wallet'), '') <> '') then
    raise exception 'need_pay';
  end if;
end $$;

-- writes a check-in unless the member already has one in the last 3 hours. true = written
create or replace function public.rf_checkin(p_gym uuid, p_membership uuid, p_via text) returns boolean
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
begin
  if exists (select 1 from checkins where membership_id = p_membership and at > now() - interval '3 hours') then
    return false;
  end if;
  insert into checkins (gym_id, membership_id, via) values (p_gym, p_membership, p_via);
  return true;
end $$;

-- ================================================================ PUBLIC

create or replace function public.gym_public(p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  if p_slug is null or char_length(p_slug) > 64 then return null; end if;
  select * into g from gyms where slug = lower(btrim(p_slug)) and status = 'live';
  if not found then return null; end if;
  return jsonb_build_object('id', g.id, 'slug', g.slug, 'name', g.name, 'name_ar', g.name_ar, 'brand', g.brand,
    'status', g.status, 'currency', g.currency, 'packages', rf_packages_public(g.id));
end $$;

-- ================================================================ OWNER

create or replace function public.owner_create_gym(p_name text, p_name_ar text, p_slug text) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; v_name text; v_name_ar text; v_slug text; g gyms;
begin
  v_uid := rf_uid();
  v_name := rf_line(p_name);
  v_name_ar := rf_line(p_name_ar);
  if v_name is null or char_length(v_name) not between 2 and 60 then raise exception 'bad_input'; end if;
  if v_name_ar is not null and char_length(v_name_ar) > 60 then raise exception 'bad_input'; end if;
  v_slug := lower(btrim(coalesce(p_slug, '')));
  if v_slug !~ '^[a-z0-9]([a-z0-9-]{1,28})[a-z0-9]$' or v_slug ~ '--' or rf_reserved_slug(v_slug) then
    raise exception 'slug_bad';
  end if;
  if exists (select 1 from gyms where owner_id = v_uid) then raise exception 'dup'; end if;
  if exists (select 1 from gyms where slug = v_slug) then raise exception 'slug_taken'; end if;
  begin
    insert into gyms (slug, name, name_ar, owner_id) values (v_slug, v_name, v_name_ar, v_uid) returning * into g;
  exception when unique_violation then
    if exists (select 1 from gyms where owner_id = v_uid) then raise exception 'dup'; end if;
    raise exception 'slug_taken';
  end;
  insert into gym_staff (gym_id, user_id, role, name)
  values (g.id, v_uid, 'owner', rf_line(auth.jwt() -> 'user_metadata' ->> 'name'));
  return rf_gym_json(g);
end $$;

create or replace function public.owner_get_gym() returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; g gyms;
begin
  v_uid := rf_uid();
  select * into g from gyms where owner_id = v_uid;
  if not found then return null; end if;
  return jsonb_build_object(
    'gym', rf_gym_json(g),
    'packages', (select coalesce(jsonb_agg(rf_pkg_json(p) order by p.sort, p.price, p.created_at), '[]'::jsonb)
                 from packages p where p.gym_id = g.id and p.deleted_at is null),
    'counts', (select jsonb_build_object(
                 'members', count(*) filter (where m.status in ('listed', 'active')),
                 'active',  count(*) filter (where m.status = 'active'),
                 'listed',  count(*) filter (where m.status = 'listed'),
                 'guests',  count(*) filter (where m.status = 'guest'))
               from memberships m where m.gym_id = g.id));
end $$;

create or replace function public.owner_update_gym(p_patch jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  g gyms; k text; v jsonb; t text;
  v_brand jsonb; v_settings jsonb; v_pay jsonb;
begin
  g := rf_owner_gym();
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception 'bad_input'; end if;
  if exists (select 1 from jsonb_object_keys(p_patch) x
             where x not in ('name', 'name_ar', 'brand', 'settings', 'pay')) then
    raise exception 'bad_input';
  end if;

  if p_patch ? 'name' then
    t := rf_line(p_patch ->> 'name');
    if jsonb_typeof(p_patch -> 'name') <> 'string' or t is null or char_length(t) not between 2 and 60 then
      raise exception 'bad_input';
    end if;
    g.name := t;
  end if;

  if p_patch ? 'name_ar' then
    if jsonb_typeof(p_patch -> 'name_ar') not in ('string', 'null') then raise exception 'bad_input'; end if;
    t := rf_line(p_patch ->> 'name_ar');
    if t is not null and char_length(t) > 60 then raise exception 'bad_input'; end if;
    g.name_ar := t;
  end if;

  if p_patch ? 'brand' then
    if jsonb_typeof(p_patch -> 'brand') <> 'object' then raise exception 'bad_input'; end if;
    v_brand := g.brand;
    for k, v in select * from jsonb_each(p_patch -> 'brand') loop
      if k in ('primary', 'accent') then
        if jsonb_typeof(v) = 'null' then v_brand := v_brand - k;
        elsif jsonb_typeof(v) = 'string' and (v #>> '{}') ~ '^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$' then
          v_brand := v_brand || jsonb_build_object(k, v #>> '{}');
        else raise exception 'bad_input';
        end if;
      elsif k = 'logo' then
        if jsonb_typeof(v) = 'null' then v_brand := v_brand - k;
        elsif jsonb_typeof(v) = 'string' and (
                rf_img_ok(v #>> '{}', 205000)
                or ((v #>> '{}') ~ '^https://[A-Za-z0-9._~:/?#@!$&()*+,;=%-]+$' and char_length(v #>> '{}') <= 300)) then
          v_brand := v_brand || jsonb_build_object(k, v #>> '{}');
        else raise exception 'bad_input';
        end if;
      else
        raise exception 'bad_input';
      end if;
    end loop;
    g.brand := v_brand;
  end if;

  if p_patch ? 'settings' then
    if jsonb_typeof(p_patch -> 'settings') <> 'object' then raise exception 'bad_input'; end if;
    v_settings := g.settings;
    for k, v in select * from jsonb_each(p_patch -> 'settings') loop
      if k = 'cross' and jsonb_typeof(v) = 'boolean' then
        v_settings := v_settings || jsonb_build_object(k, v);
      elsif k = 'posts' and jsonb_typeof(v) = 'string' and (v #>> '{}') in ('all', 'approve', 'off') then
        v_settings := v_settings || jsonb_build_object(k, v);
      else
        raise exception 'bad_input';
      end if;
    end loop;
    g.settings := v_settings;
  end if;

  if p_patch ? 'pay' then
    if jsonb_typeof(p_patch -> 'pay') <> 'object' then raise exception 'bad_input'; end if;
    v_pay := g.pay;
    for k, v in select * from jsonb_each(p_patch -> 'pay') loop
      if k = 'cash' and jsonb_typeof(v) = 'boolean' then
        v_pay := v_pay || jsonb_build_object(k, v);
      elsif k in ('instapay', 'wallet') then
        t := case when jsonb_typeof(v) = 'string' then rf_line(v #>> '{}') end;
        if jsonb_typeof(v) not in ('string', 'null') then raise exception 'bad_input'; end if;
        if t is null then v_pay := v_pay - k;
        elsif (k = 'instapay' and char_length(t) <= 100) or (k = 'wallet' and char_length(t) <= 30) then
          v_pay := v_pay || jsonb_build_object(k, t);
        else raise exception 'bad_input';
        end if;
      else
        raise exception 'bad_input';
      end if;
    end loop;
    g.pay := v_pay;
  end if;

  update gyms set name = g.name, name_ar = g.name_ar, brand = g.brand, settings = g.settings, pay = g.pay
  where id = g.id;
  if g.status = 'live' then perform rf_check_live(g.id); end if;
  return rf_gym_json(g);
end $$;

create or replace function public.owner_upsert_package(p jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  g gyms; r packages; v_new boolean := true; v_id uuid;
begin
  g := rf_owner_gym();
  if p is null or jsonb_typeof(p) <> 'object' then raise exception 'bad_input'; end if;
  if exists (select 1 from jsonb_object_keys(p) x
             where x not in ('id', 'name', 'name_ar', 'months', 'price', 'before_price', 'until', 'active', 'sort')) then
    raise exception 'bad_input';
  end if;

  v_id := rf_uuid(p ->> 'id');
  if v_id is not null then
    select * into r from packages where id = v_id and gym_id = g.id and deleted_at is null for update;
    if not found then raise exception 'not_found'; end if;
    v_new := false;
  else
    if (select count(*) from packages where gym_id = g.id and deleted_at is null) >= 20 then
      raise exception 'limit';
    end if;
    r.active := true;
    r.sort := 0;
  end if;

  if p ? 'name' then r.name := rf_line(p ->> 'name'); end if;
  if p ? 'name_ar' then r.name_ar := rf_line(p ->> 'name_ar'); end if;
  if p ? 'months' then r.months := rf_int(p ->> 'months'); end if;
  if p ? 'price' then r.price := rf_int(p ->> 'price'); end if;
  if p ? 'before_price' then r.before_price := rf_int(p ->> 'before_price'); end if;
  if p ? 'until' then r.until := rf_date(p ->> 'until'); end if;
  if p ? 'active' then
    if jsonb_typeof(p -> 'active') <> 'boolean' then raise exception 'bad_input'; end if;
    r.active := (p ->> 'active')::boolean;
  end if;
  if p ? 'sort' and jsonb_typeof(p -> 'sort') <> 'null' then r.sort := rf_int(p ->> 'sort'); end if;

  if r.name is null or char_length(r.name) > 60 then raise exception 'bad_input'; end if;
  if r.name_ar is not null and char_length(r.name_ar) > 60 then raise exception 'bad_input'; end if;
  if r.months is null or r.months not between 1 and 36 then raise exception 'bad_input'; end if;
  if r.price is null or r.price <= 0 or r.price > 10000000 then raise exception 'bad_input'; end if;
  if r.sort is null or r.sort not between -100000 and 100000 then raise exception 'bad_input'; end if;
  if r.before_price is not null then
    if r.until is null then raise exception 'before_needs_until'; end if;
    if r.before_price <= r.price or r.before_price > 10000000 then raise exception 'bad_input'; end if;
  end if;

  if v_new then
    insert into packages (gym_id, name, name_ar, months, price, before_price, until, active, sort)
    values (g.id, r.name, r.name_ar, r.months, r.price, r.before_price, r.until, r.active, r.sort)
    returning * into r;
  else
    update packages set name = r.name, name_ar = r.name_ar, months = r.months, price = r.price,
      before_price = r.before_price, until = r.until, active = r.active, sort = r.sort
    where id = r.id returning * into r;
  end if;
  if g.status = 'live' then perform rf_check_live(g.id); end if;
  return rf_pkg_json(r);
end $$;

create or replace function public.owner_delete_package(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  g := rf_owner_gym();
  update packages set deleted_at = now(), active = false
  where id = p_id and gym_id = g.id and deleted_at is null;
  if not found then raise exception 'not_found'; end if;
  if g.status = 'live' then perform rf_check_live(g.id); end if;
  return jsonb_build_object('ok', true);
end $$;

-- errors[].row is the 0 based index in p_rows; codes: bad_row, bad_phone, bad_name, bad_gender, bad_package, bad_date
create or replace function public.owner_import_members(p_rows jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  g gyms; r jsonb; i int := -1;
  v_added int := 0; v_updated int := 0; v_errors jsonb := '[]'::jsonb;
  v_phone text; v_name text; v_gender text; v_pkg packages; v_pkg_id uuid; v_starts date; v_ends date;
  m memberships; v_code text;
begin
  g := rf_owner_gym();
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then raise exception 'bad_input'; end if;
  if jsonb_array_length(p_rows) > 2000 then raise exception 'limit'; end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    i := i + 1;
    v_code := null; v_pkg_id := null; v_starts := null; v_ends := null; v_gender := null;
    if jsonb_typeof(r) <> 'object' then
      v_code := 'bad_row';
    else
      v_phone := rf_phone(r ->> 'phone');
      v_name := rf_line(r ->> 'name');
      if v_phone is null then v_code := 'bad_phone';
      elsif v_name is null or char_length(v_name) not between 2 and 60 then v_code := 'bad_name';
      end if;
      if v_code is null and coalesce(btrim(r ->> 'gender'), '') <> '' then
        v_gender := rf_gender(r ->> 'gender');
        if v_gender is null then v_code := 'bad_gender'; end if;
      end if;
      if v_code is null and coalesce(btrim(r ->> 'package_id'), '') <> '' then
        begin
          select * into v_pkg from packages
          where id = (r ->> 'package_id')::uuid and gym_id = g.id and deleted_at is null;
          if found then v_pkg_id := v_pkg.id; else v_code := 'bad_package'; end if;
        exception when others then v_code := 'bad_package';
        end;
      end if;
      if v_code is null then
        begin
          v_starts := rf_date(r ->> 'starts');
          v_ends := rf_date(r ->> 'ends');
          if v_starts is not null and v_ends is not null and v_ends < v_starts then v_code := 'bad_date'; end if;
          if v_starts is not null and v_ends is null and v_pkg_id is not null then
            v_ends := (v_starts + make_interval(months => v_pkg.months))::date;
          end if;
        exception when others then v_code := 'bad_date';
        end;
      end if;
    end if;

    if v_code is not null then
      v_errors := v_errors || jsonb_build_object('row', i, 'code', v_code);
      continue;
    end if;

    select * into m from memberships where gym_id = g.id and phone = v_phone for update;
    if found then
      update memberships set
        name = v_name,
        gender = coalesce(v_gender, gender),
        package_id = coalesce(v_pkg_id, package_id),
        starts = coalesce(v_starts, starts),
        ends = coalesce(v_ends, ends),
        status = case when status = 'guest' then 'active' else status end
      where id = m.id;
      v_updated := v_updated + 1;
    else
      insert into memberships (gym_id, phone, name, gender, package_id, starts, ends, status)
      values (g.id, v_phone, v_name, v_gender, v_pkg_id, v_starts, v_ends, 'listed');
      v_added := v_added + 1;
    end if;
  end loop;

  return jsonb_build_object('added', v_added, 'updated', v_updated, 'errors', v_errors);
end $$;

create or replace function public.owner_go_live() returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  g := rf_owner_gym();
  perform rf_check_live(g.id);
  update gyms set status = 'live' where id = g.id returning * into g;
  return rf_gym_json(g);
end $$;

create or replace function public.owner_home() returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare g gyms; v_needs jsonb; v_stats jsonb;
begin
  g := rf_owner_gym();

  select coalesce(jsonb_agg(n.j order by n.at), '[]'::jsonb) into v_needs from (
    select x.at, x.j from (
      -- payments waiting for a decision
      select pay.created_at as at, jsonb_build_object('k', 'pay', 'id', pay.id, 'at', pay.created_at, 'name', m.name,
               'phone', m.phone, 'membership_id', m.id, 'amount', pay.amount, 'method', pay.method, 'ref', pay.ref,
               'package', rf_pkg_brief(pay.package_id), 'ends', m.ends, 'member_status', m.status) as j
      from payments pay join memberships m on m.id = pay.membership_id
      where pay.gym_id = g.id and pay.status = 'pending'
      union all
      -- people who joined but are not on the list
      select m.created_at, jsonb_build_object('k', 'guest', 'id', m.id, 'at', m.created_at, 'name', m.name,
               'phone', m.phone, 'gender', m.gender)
      from memberships m where m.gym_id = g.id and m.status = 'guest'
      union all
      -- reports always reach the owner with the post attached
      select r.at, jsonb_build_object('k', 'report', 'id', r.id, 'at', r.at,
               'name', (select p.name from profiles p where p.user_id = r.by_user),
               'reason', r.reason,
               'about', case when r.about_user is null then null else
                   jsonb_build_object('user_id', r.about_user,
                     'name', (select p.name from profiles p where p.user_id = r.about_user)) end,
               'post', (select jsonb_build_object('id', po.id, 'body', po.body, 'img', po.img, 'status', po.status, 'at', po.at)
                        from posts po where po.id = r.about_post))
      from reports r where r.gym_id = g.id and r.status = 'open'
      union all
      -- posts waiting for approval; the owner sees a post only if its author has vis = 'all'
      select po.at, jsonb_build_object('k', 'post', 'id', po.id, 'at', po.at, 'name', p.name,
               'body', po.body, 'img', po.img)
      from posts po join profiles p on p.user_id = po.by_user
      where po.gym_id = g.id and po.status = 'pending' and p.vis = 'all'
    ) x order by x.at limit 200
  ) n;

  select jsonb_build_object(
    'members', (select count(*) from memberships m where m.gym_id = g.id and m.status in ('listed', 'active')),
    'active_now', (select count(distinct c.membership_id) from checkins c
                   where c.gym_id = g.id and c.at > now() - interval '2 hours'),
    'checkins_today', (select count(*) from checkins c where c.gym_id = g.id and c.at >= rf_day_start()),
    'expiring_7d', (select count(*) from memberships m where m.gym_id = g.id and m.status in ('listed', 'active')
                    and m.ends between rf_today() and rf_today() + 7),
    'refkas', (select count(*) from refkas r where r.gym_id = g.id and r.ended_at is null)
  ) into v_stats;

  return jsonb_build_object('gym', rf_gym_json(g), 'needs', v_needs, 'stats', v_stats);
end $$;

create or replace function public.owner_members(p_q text default '') returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare g gyms; v_q text; v_digits text;
begin
  g := rf_owner_gym();
  v_q := lower(coalesce(rf_line(left(p_q, 80)), ''));
  v_digits := regexp_replace(v_q, '[^0-9]', '', 'g');
  if v_digits ~ '^0[0-9]' then v_digits := substr(v_digits, 2); end if;   -- 010.. also finds +2010..
  return (
    select coalesce(jsonb_agg(x.j order by x.name, x.id), '[]'::jsonb) from (
      select m.name, m.id, jsonb_build_object('id', m.id, 'name', m.name, 'phone', m.phone, 'gender', m.gender,
               'status', m.status, 'package', rf_pkg_brief(m.package_id), 'starts', m.starts, 'ends', m.ends,
               'joined', m.user_id is not null,
               'last_checkin', (select max(c.at) from checkins c where c.membership_id = m.id)) as j
      from memberships m
      where m.gym_id = g.id
        and (v_q = '' or position(v_q in lower(m.name)) > 0
             or (v_digits <> '' and position(v_digits in m.phone) > 0))
      order by m.name, m.id
      limit 2000
    ) x);
end $$;

create or replace function public.owner_decide_payment(p_id uuid, p_ok boolean) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms; pay payments; m memberships; pk packages; v_from date; v_ends date;
begin
  g := rf_owner_gym();
  if p_ok is null then raise exception 'bad_input'; end if;
  select * into pay from payments where id = p_id and gym_id = g.id and status = 'pending' for update;
  if not found then raise exception 'not_found'; end if;

  if p_ok then
    select * into m from memberships where id = pay.membership_id and gym_id = g.id for update;
    if not found then raise exception 'not_found'; end if;
    select * into pk from packages where id = pay.package_id and gym_id = g.id;
    if not found then raise exception 'not_found'; end if;
    v_from := greatest(rf_today(), coalesce(m.ends, rf_today()));
    v_ends := (v_from + make_interval(months => pk.months))::date;
    update memberships set
      package_id = pk.id,
      starts = case when m.starts is null or m.ends is null or m.ends < rf_today() then rf_today() else m.starts end,
      ends = v_ends,
      status = case when m.user_id is not null then 'active' else m.status end
    where id = m.id;
  end if;

  update payments set status = case when p_ok then 'ok' else 'rejected' end,
    decided_by = auth.uid(), decided_at = now()
  where id = pay.id;
  return jsonb_build_object('ok', true, 'ends', v_ends);
end $$;

create or replace function public.owner_decide_guest(p_membership_id uuid, p_ok boolean,
  p_package_id uuid default null, p_ends date default null) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms; m memberships; pk packages; v_ends date;
begin
  g := rf_owner_gym();
  if p_ok is null then raise exception 'bad_input'; end if;
  select * into m from memberships where id = p_membership_id and gym_id = g.id and status = 'guest' for update;
  if not found then raise exception 'not_found'; end if;

  if not p_ok then
    delete from memberships where id = m.id;      -- cascades to his pending payment, if any
    return jsonb_build_object('ok', true);
  end if;

  if p_package_id is not null then
    select * into pk from packages where id = p_package_id and gym_id = g.id and deleted_at is null;
    if not found then raise exception 'not_found'; end if;
  end if;
  if p_ends is not null and (p_ends < rf_today() or p_ends > rf_today() + 3660) then
    raise exception 'bad_input';
  end if;
  v_ends := coalesce(p_ends, case when pk.id is not null
                                  then (rf_today() + make_interval(months => pk.months))::date end);
  update memberships set status = 'active', package_id = pk.id, starts = rf_today(), ends = v_ends
  where id = m.id;
  return jsonb_build_object('ok', true, 'ends', v_ends);
end $$;

create or replace function public.owner_decide_post(p_id uuid, p_action text) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  g := rf_owner_gym();
  if p_action is null or p_action not in ('approve', 'hide') then raise exception 'bad_input'; end if;
  update posts set status = case when p_action = 'approve' then 'live' else 'hidden' end
  where id = p_id and gym_id = g.id;
  if not found then raise exception 'not_found'; end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.owner_resolve_report(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms;
begin
  g := rf_owner_gym();
  update reports set status = 'done' where id = p_id and gym_id = g.id;
  if not found then raise exception 'not_found'; end if;
  return jsonb_build_object('ok', true);
end $$;

-- Token problems raise: bad_input (garbage, wrong gym, bad signature) or expired (too old, or already used).
-- A good token of a member whose membership is over returns {ok:false, valid:false, name, ends}.
create or replace function public.owner_scan(p_token text) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  g gyms; m memberships; v_parts text[]; v_bucket bigint; v_now bigint; v_written boolean;
begin
  g := rf_owner_gym();
  if p_token is null or char_length(p_token) > 120 then raise exception 'bad_input'; end if;
  v_parts := string_to_array(btrim(p_token), '.');
  if array_length(v_parts, 1) is distinct from 4 or v_parts[1] <> 'rf1'
     or v_parts[2] !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     or v_parts[3] !~ '^[0-9]{1,12}$'
     or v_parts[4] !~ '^[0-9a-f]{32}$' then
    raise exception 'bad_input';
  end if;
  v_bucket := v_parts[3]::bigint;

  select * into m from memberships where id = v_parts[2]::uuid and gym_id = g.id for update;
  if not found then raise exception 'bad_input'; end if;          -- another gym's member looks like garbage
  if rf_qr_sig(g.qr_secret, m.id, v_bucket) <> v_parts[4] then raise exception 'bad_input'; end if;

  v_now := floor(extract(epoch from clock_timestamp()) / 60)::bigint;
  if v_bucket > v_now then raise exception 'bad_input'; end if;
  if v_bucket < v_now - 1 then raise exception 'expired'; end if;  -- current and previous bucket only

  if m.qr_used_bucket is not null and v_bucket <= m.qr_used_bucket then
    -- the camera often fires twice: the very same token within 10 s is answered again, anything else is a replay
    if v_bucket = m.qr_used_bucket and m.qr_used_at > clock_timestamp() - interval '10 seconds' then
      return jsonb_build_object('ok', true, 'valid', true, 'name', m.name, 'ends', m.ends, 'already', true);
    end if;
    raise exception 'expired';
  end if;

  if m.status <> 'active' or m.user_id is null or (m.ends is not null and m.ends < rf_today()) then
    return jsonb_build_object('ok', false, 'valid', false, 'name', m.name, 'ends', m.ends, 'already', false);
  end if;

  update memberships set qr_used_bucket = v_bucket, qr_used_at = clock_timestamp() where id = m.id;
  v_written := rf_checkin(g.id, m.id, 'qr');
  return jsonb_build_object('ok', true, 'valid', true, 'name', m.name, 'ends', m.ends, 'already', not v_written);
end $$;

create or replace function public.owner_checkin(p_membership_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare g gyms; m memberships; v_written boolean;
begin
  g := rf_owner_gym();
  select * into m from memberships where id = p_membership_id and gym_id = g.id for update;
  if not found then raise exception 'not_found'; end if;
  if m.status = 'guest' then raise exception 'not_member'; end if;
  if m.ends is not null and m.ends < rf_today() then raise exception 'expired'; end if;
  v_written := rf_checkin(g.id, m.id, 'desk');
  return jsonb_build_object('ok', true, 'already', not v_written);
end $$;

-- ==================================================================== 0003_member_functions.sql
-- Refka v1 functions, part 2: member RPCs. Same rules as 0002.
-- p_gym arguments are text and accept the gym id or its slug.

create or replace function public.me() returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; p profiles;
begin
  v_uid := rf_uid();
  select * into p from profiles where user_id = v_uid;
  return jsonb_build_object(
    'profile', case when p.user_id is null then null else rf_profile_json(p) end,
    'memberships', (select coalesce(jsonb_agg(rf_membership_json(m) order by m.created_at), '[]'::jsonb)
                    from memberships m where m.user_id = v_uid),
    'is_owner', exists (select 1 from gyms g where g.owner_id = v_uid));
end $$;

create or replace function public.member_join(p_slug text, p_name text, p_gender text, p_birth_year int)
returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare
  v_uid uuid; v_phone text; g gyms; p profiles; m memberships;
  v_name text; v_gender text; v_year int; v_matched boolean := false;
begin
  v_uid := rf_uid();
  v_phone := my_phone();
  if v_phone is null then raise exception 'bad_input'; end if;       -- not a phone account
  if p_slug is null or char_length(p_slug) > 64 then raise exception 'not_found'; end if;
  select * into g from gyms where slug = lower(btrim(p_slug)) and status = 'live';
  if not found then raise exception 'not_found'; end if;

  select * into m from memberships where gym_id = g.id and phone = v_phone for update;
  if m.id is not null and m.user_id is not null and m.user_id <> v_uid then raise exception 'dup'; end if;

  select * into p from profiles where user_id = v_uid;
  if not found then
    v_name := rf_line(p_name);
    if v_name is null or char_length(v_name) not between 2 and 60 then raise exception 'bad_input'; end if;
    if p_gender is null or p_gender not in ('m', 'f') then raise exception 'bad_input'; end if;
    v_year := extract(year from rf_today())::int;
    if p_birth_year is null or p_birth_year < v_year - 90 or p_birth_year > v_year - 13 then
      raise exception 'bad_input';
    end if;
    -- when the gym already knows this phone's gender, the gym's record wins over the typed one
    v_gender := coalesce(m.gender, p_gender);
    begin
      insert into profiles (user_id, phone, name, gender, birth_year, vis)
      values (v_uid, v_phone, v_name, v_gender, p_birth_year, case when v_gender = 'f' then 'gender' else 'all' end)
      returning * into p;
    exception when unique_violation then raise exception 'dup';
    end;
  end if;
  -- an existing profile keeps its name, gender and birth year: they cannot be changed by joining again

  if m.id is null then
    -- already in this gym under an older row? (cannot normally happen, the phone is final)
    select * into m from memberships where gym_id = g.id and user_id = v_uid;
    if not found then
      if (select count(*) from memberships where gym_id = g.id and status = 'guest') >= 500 then
        raise exception 'limit';
      end if;
      insert into memberships (gym_id, phone, name, gender, user_id, status)
      values (g.id, v_phone, p.name, p.gender, v_uid, 'guest') returning * into m;
    end if;
  elsif m.user_id is null then
    update memberships set user_id = v_uid, status = 'active', gender = coalesce(gender, p.gender)
    where id = m.id returning * into m;
    v_matched := true;
  end if;
  if m.status = 'active' then v_matched := true; end if;

  return jsonb_build_object('membership', rf_membership_json(m), 'matched', v_matched);
end $$;

create or replace function public.update_profile(p_patch jsonb) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; p profiles; t text; v_old_vis text; v_times text[];
begin
  v_uid := rf_uid();
  select * into p from profiles where user_id = v_uid for update;
  if not found then raise exception 'not_found'; end if;
  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then raise exception 'bad_input'; end if;
  if exists (select 1 from jsonb_object_keys(p_patch) x
             where x not in ('name', 'bio', 'goal', 'level', 'times', 'vis', 'avatar')) then
    raise exception 'bad_input';
  end if;
  v_old_vis := p.vis;

  if p_patch ? 'name' then
    t := rf_line(p_patch ->> 'name');
    if jsonb_typeof(p_patch -> 'name') <> 'string' or t is null or char_length(t) not between 2 and 60 then
      raise exception 'bad_input';
    end if;
    p.name := t;
  end if;
  if p_patch ? 'bio' then
    if jsonb_typeof(p_patch -> 'bio') not in ('string', 'null') then raise exception 'bad_input'; end if;
    t := nullif(btrim(p_patch ->> 'bio'), '');
    if t is not null and char_length(t) > 300 then raise exception 'bad_input'; end if;
    p.bio := t;
  end if;
  if p_patch ? 'goal' then
    if jsonb_typeof(p_patch -> 'goal') not in ('string', 'null') then raise exception 'bad_input'; end if;
    t := rf_line(p_patch ->> 'goal');
    if t is not null and char_length(t) > 40 then raise exception 'bad_input'; end if;
    p.goal := t;
  end if;
  if p_patch ? 'level' then
    if jsonb_typeof(p_patch -> 'level') not in ('string', 'null') then raise exception 'bad_input'; end if;
    t := rf_line(p_patch ->> 'level');
    if t is not null and char_length(t) > 40 then raise exception 'bad_input'; end if;
    p.level := t;
  end if;
  if p_patch ? 'times' then
    if jsonb_typeof(p_patch -> 'times') = 'null' then
      p.times := '{}';
    elsif jsonb_typeof(p_patch -> 'times') = 'array' then
      if jsonb_array_length(p_patch -> 'times') > 12
         or exists (select 1 from jsonb_array_elements(p_patch -> 'times') e
                    where jsonb_typeof(e) <> 'string' or char_length(btrim(e #>> '{}')) not between 1 and 20) then
        raise exception 'bad_input';
      end if;
      select coalesce(array_agg(distinct btrim(e #>> '{}')), '{}') into v_times
      from jsonb_array_elements(p_patch -> 'times') e;
      p.times := v_times;
    else
      raise exception 'bad_input';
    end if;
  end if;
  if p_patch ? 'vis' then
    if jsonb_typeof(p_patch -> 'vis') <> 'string' or (p_patch ->> 'vis') not in ('all', 'gender', 'none') then
      raise exception 'bad_input';
    end if;
    p.vis := p_patch ->> 'vis';
  end if;
  if p_patch ? 'avatar' then
    if jsonb_typeof(p_patch -> 'avatar') = 'null' then
      p.avatar := null;
    elsif jsonb_typeof(p_patch -> 'avatar') = 'string' and rf_img_ok(p_patch ->> 'avatar', 56000) then
      p.avatar := p_patch ->> 'avatar';
    else
      raise exception 'bad_input';
    end if;
  end if;

  update profiles set name = p.name, bio = p.bio, goal = p.goal, level = p.level, times = p.times,
    vis = p.vis, avatar = p.avatar
  where user_id = v_uid;

  if v_old_vis = 'all' and p.vis <> 'all' then
    -- the owner may no longer look at this member's posts, so nothing of his can wait for approval
    update posts set status = 'live' where by_user = v_uid and status = 'pending';
  end if;
  if v_old_vis <> p.vis then
    -- pending requests with people who can no longer see each other are withdrawn
    update requests r set status = 'cancelled', decided_at = now()
    where r.status = 'pending' and (r.from_user = v_uid or r.to_user = v_uid)
      and not rf_mutual(r.from_user, r.to_user, r.gym_id);
  end if;
  return rf_profile_json(p);
end $$;

create or replace function public.member_home(p_gym text) returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare
  v_uid uuid; g gyms; m memberships; v_qr jsonb; v_bucket bigint; v_gender text; v_here int;
begin
  v_uid := rf_uid();
  g := rf_gym(p_gym);
  select * into m from memberships where gym_id = g.id and user_id = v_uid;
  if not found then raise exception 'not_member'; end if;

  if m.status = 'active' and (m.ends is null or m.ends >= rf_today()) then
    v_bucket := floor(extract(epoch from clock_timestamp()) / 60)::bigint;
    v_qr := jsonb_build_object(
      'token', rf_qr_token(g.qr_secret, m.id, v_bucket),
      'exp', (v_bucket + 1) * 60,                                   -- epoch seconds: fetch a new one then
      'exp_at', to_timestamp((v_bucket + 1) * 60),
      'ttl', greatest(1, ((v_bucket + 1) * 60 - floor(extract(epoch from clock_timestamp())))::int));
  end if;

  -- "here now" only counts people this member is allowed to see (plus himself), so it cannot be used
  -- to learn that a hidden member walked in
  if rf_active(m) then
    select coalesce(m.gender, p.gender) into v_gender from profiles p where p.user_id = v_uid;
    select count(distinct c.membership_id) into v_here
    from checkins c join memberships x on x.id = c.membership_id
    where c.gym_id = g.id and c.at > now() - interval '2 hours'
      and ( x.user_id = v_uid
            or (x.user_id is not null and can_see(v_uid, x.user_id, g.id))
            or (x.user_id is null and x.gender is not distinct from v_gender) );
  else
    v_here := 0;
  end if;

  return jsonb_build_object(
    'gym', rf_gym_brief(g) || jsonb_build_object('currency', g.currency, 'settings', g.settings, 'pay', g.pay,
             'status', g.status, 'packages', rf_packages_public(g.id)),
    'membership', jsonb_build_object('id', m.id, 'status', m.status, 'package', rf_pkg_brief(m.package_id),
             'starts', m.starts, 'ends', m.ends,
             'days_left', case when m.ends is null then null else m.ends - rf_today() end),
    'qr', v_qr,
    'here_now', v_here,
    'week_checkins', (select count(*) from checkins c where c.membership_id = m.id and c.at > now() - interval '7 days'),
    'pending_payment', exists (select 1 from payments pay where pay.membership_id = m.id and pay.status = 'pending'));
end $$;

create or replace function public.member_renew(p_gym text, p_package_id uuid, p_method text, p_ref text)
returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; g gyms; m memberships; pk packages; v_ref text; pay payments;
begin
  v_uid := rf_uid();
  g := rf_gym(p_gym);
  select * into m from memberships where gym_id = g.id and user_id = v_uid for update;
  if not found then raise exception 'not_member'; end if;
  if g.status <> 'live' then raise exception 'not_found'; end if;
  select * into pk from packages where id = p_package_id and gym_id = g.id and active and deleted_at is null;
  if not found then raise exception 'not_found'; end if;

  if p_method is null or p_method not in ('instapay', 'wallet', 'cash') then raise exception 'bad_input'; end if;
  if (p_method = 'cash' and not coalesce((g.pay ->> 'cash') = 'true', false))
     or (p_method in ('instapay', 'wallet') and coalesce(btrim(g.pay ->> p_method), '') = '') then
    raise exception 'bad_input';                                    -- the gym does not take this method
  end if;
  v_ref := rf_line(p_ref);
  if v_ref is not null and char_length(v_ref) > 60 then raise exception 'bad_input'; end if;
  if p_method <> 'cash' and (v_ref is null or char_length(v_ref) < 4) then raise exception 'bad_input'; end if;

  if exists (select 1 from payments where membership_id = m.id and status = 'pending') then
    raise exception 'pending_exists';
  end if;
  begin
    insert into payments (gym_id, membership_id, package_id, amount, method, ref)
    values (g.id, m.id, pk.id, rf_pkg_price(pk), p_method, v_ref) returning * into pay;
  exception when unique_violation then raise exception 'pending_exists';
  end;
  return jsonb_build_object('payment', jsonb_build_object('id', pay.id, 'amount', pay.amount, 'method', pay.method,
    'ref', pay.ref, 'status', pay.status, 'created_at', pay.created_at, 'package', rf_pkg_brief(pay.package_id)));
end $$;

-- ================================================================ people and requests

create or replace function public.people(p_gym text, p_q text default '') returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; me_m memberships; me_p profiles; v_q text;
begin
  me_m := rf_member(p_gym);
  v_uid := me_m.user_id;
  select * into me_p from profiles where user_id = v_uid;
  v_q := lower(coalesce(rf_line(left(p_q, 60)), ''));
  return (
    select coalesce(jsonb_agg(x.j order by x.overlap desc, x.name, x.user_id), '[]'::jsonb) from (
      select p.name, p.user_id, o.overlap,
        jsonb_build_object('user_id', p.user_id, 'name', p.name, 'gender', coalesce(m.gender, p.gender),
          'goal', p.goal, 'level', p.level, 'times', to_jsonb(p.times), 'bio', p.bio, 'avatar', p.avatar,
          'overlap', o.overlap,
          'relation', case
            when exists (select 1 from refkas r where r.gym_id = m.gym_id and r.ended_at is null
                         and r.a = least(v_uid, p.user_id) and r.b = greatest(v_uid, p.user_id)) then 'refka'
            when exists (select 1 from requests q where q.gym_id = m.gym_id and q.status = 'pending'
                         and q.from_user = v_uid and q.to_user = p.user_id) then 'out'
            when exists (select 1 from requests q where q.gym_id = m.gym_id and q.status = 'pending'
                         and q.from_user = p.user_id and q.to_user = v_uid) then 'in'
            else 'none' end) as j
      from memberships m
      join profiles p on p.user_id = m.user_id
      cross join lateral (select count(*)::int as overlap from unnest(p.times) t where t = any (me_p.times)) o
      where m.gym_id = me_m.gym_id and m.status = 'active' and m.user_id <> v_uid
        and can_see(v_uid, m.user_id, m.gym_id)
        and (v_q = '' or position(v_q in lower(p.name)) > 0)
      order by o.overlap desc, p.name, p.user_id
      limit 100
    ) x);
end $$;

create or replace function public.request_send(p_gym text, p_to uuid, p_kind text, p_slot text) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; m memberships; v_slot text; r requests;
begin
  m := rf_member(p_gym);
  v_uid := m.user_id;
  if p_to is null or p_to = v_uid then raise exception 'bad_input'; end if;
  if p_kind is null or p_kind not in ('train', 'spot') then raise exception 'bad_input'; end if;
  v_slot := rf_line(p_slot);
  if v_slot is not null and char_length(v_slot) > 40 then raise exception 'bad_input'; end if;

  -- both must be able to see each other. A block answers "hidden" too, so nobody learns he was blocked.
  if not rf_mutual(v_uid, p_to, m.gym_id) then raise exception 'hidden'; end if;

  if exists (select 1 from refkas x where x.gym_id = m.gym_id and x.ended_at is null
             and x.a = least(v_uid, p_to) and x.b = greatest(v_uid, p_to)) then
    raise exception 'dup';
  end if;
  if exists (select 1 from requests q where q.gym_id = m.gym_id and q.status = 'pending'
             and ((q.from_user = v_uid and q.to_user = p_to) or (q.from_user = p_to and q.to_user = v_uid))) then
    raise exception 'dup';
  end if;
  -- no means no: after a decline the same person cannot be asked again for 14 days
  if exists (select 1 from requests q where q.gym_id = m.gym_id and q.status = 'declined'
             and q.from_user = v_uid and q.to_user = p_to and q.decided_at > now() - interval '14 days') then
    raise exception 'dup';
  end if;
  -- 5 a day over all gyms; cancelled ones count, so cancel and resend cannot be used to pester
  if (select count(*) from requests q where q.from_user = v_uid and q.created_at >= rf_day_start()) >= 5 then
    raise exception 'limit';
  end if;

  begin
    insert into requests (gym_id, from_user, to_user, kind, slot)
    values (m.gym_id, v_uid, p_to, p_kind, v_slot) returning * into r;
  exception when unique_violation then raise exception 'dup';
  end;
  return jsonb_build_object('request', jsonb_build_object('id', r.id, 'kind', r.kind, 'slot', r.slot,
    'status', r.status, 'at', r.created_at, 'to', rf_person(r.to_user, true)));
end $$;

create or replace function public.request_respond(p_id uuid, p_accept boolean) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; r requests; v_refka uuid; m memberships;
begin
  v_uid := rf_uid();
  if p_accept is null then raise exception 'bad_input'; end if;
  select * into r from requests where id = p_id and to_user = v_uid and status = 'pending' for update;
  if not found then raise exception 'not_found'; end if;
  select * into m from memberships where gym_id = r.gym_id and user_id = v_uid;
  if not found or not rf_active(m) then raise exception 'not_member'; end if;

  if not p_accept then
    update requests set status = 'declined', decided_at = now() where id = r.id;
    return jsonb_build_object('ok', true);
  end if;

  if not rf_mutual(v_uid, r.from_user, r.gym_id) then raise exception 'hidden'; end if;
  update requests set status = 'accepted', decided_at = now() where id = r.id;
  insert into refkas (gym_id, a, b)
  values (r.gym_id, least(r.from_user, r.to_user), greatest(r.from_user, r.to_user))
  on conflict do nothing
  returning id into v_refka;
  if v_refka is null then
    select id into v_refka from refkas
    where gym_id = r.gym_id and ended_at is null
      and a = least(r.from_user, r.to_user) and b = greatest(r.from_user, r.to_user);
  end if;
  return jsonb_build_object('ok', true, 'refka_id', v_refka);
end $$;

create or replace function public.request_cancel(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid;
begin
  v_uid := rf_uid();
  update requests set status = 'cancelled', decided_at = now()
  where id = p_id and from_user = v_uid and status = 'pending';
  if not found then raise exception 'not_found'; end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.requests_list(p_gym text) returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; m memberships;
begin
  m := rf_member(p_gym);
  v_uid := m.user_id;
  return jsonb_build_object(
    'incoming', (
      select coalesce(jsonb_agg(x.j order by x.created_at desc), '[]'::jsonb) from (
        select r.created_at, jsonb_build_object('id', r.id, 'kind', r.kind, 'slot', r.slot, 'at', r.created_at,
                 'from', rf_person(r.from_user, true)) as j
        from requests r
        where r.gym_id = m.gym_id and r.to_user = v_uid and r.status = 'pending'
          and rf_mutual(v_uid, r.from_user, r.gym_id)
        order by r.created_at desc limit 50) x),
    'outgoing', (
      select coalesce(jsonb_agg(x.j order by x.created_at desc), '[]'::jsonb) from (
        select r.created_at, jsonb_build_object('id', r.id, 'kind', r.kind, 'slot', r.slot, 'at', r.created_at,
                 'status', r.status, 'to', rf_person(r.to_user, true)) as j
        from requests r
        where r.gym_id = m.gym_id and r.from_user = v_uid
          and (r.status = 'pending'
               or (r.status in ('accepted', 'declined') and r.created_at > now() - interval '14 days'))
          and can_see(v_uid, r.to_user, r.gym_id, true)
        order by r.created_at desc limit 50) x));
end $$;

-- ================================================================ refkas and chat

-- the open refka p_refka if the caller is one of the two and may still deal with the other, else an error
create or replace function public.rf_refka(p_refka uuid) returns public.refkas
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; r refkas; v_other uuid; m memberships;
begin
  v_uid := rf_uid();
  select * into r from refkas where id = p_refka and (a = v_uid or b = v_uid) and ended_at is null;
  if not found then raise exception 'not_found'; end if;
  v_other := case when r.a = v_uid then r.b else r.a end;
  if exists (select 1 from blocks k where (k.blocker = v_uid and k.blocked = v_other)
                                       or (k.blocker = v_other and k.blocked = v_uid)) then
    raise exception 'blocked';
  end if;
  select * into m from memberships where gym_id = r.gym_id and user_id = v_uid;
  if not found or not rf_active(m) then raise exception 'not_member'; end if;
  if not rf_mutual(v_uid, v_other, r.gym_id, true) then raise exception 'hidden'; end if;
  return r;
end $$;

create or replace function public.refkas_list(p_gym text) returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; m memberships;
begin
  m := rf_member(p_gym);
  v_uid := m.user_id;
  return (
    select coalesce(jsonb_agg(x.j order by x.sort_at desc), '[]'::jsonb) from (
      select coalesce(l.at, r.since) as sort_at,
        jsonb_build_object('id', r.id, 'since', r.since,
          'with', rf_person(o.other),
          'last', case when l.id is null then null else
                    jsonb_build_object('body', l.body, 'at', l.at, 'mine', l.from_user = v_uid) end,
          'unread', (select count(*) from messages x2
                     where x2.refka_id = r.id and x2.from_user <> v_uid
                       and x2.at > coalesce(case when r.a = v_uid then r.a_read_at else r.b_read_at end,
                                            '-infinity'::timestamptz))) as j
      from refkas r
      cross join lateral (select case when r.a = v_uid then r.b else r.a end as other) o
      left join lateral (select x1.* from messages x1 where x1.refka_id = r.id order by x1.at desc limit 1) l on true
      where r.gym_id = m.gym_id and r.ended_at is null and (r.a = v_uid or r.b = v_uid)
        and rf_mutual(v_uid, o.other, r.gym_id, true)
      order by sort_at desc limit 200
    ) x);
end $$;

create or replace function public.refka_end(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid;
begin
  v_uid := rf_uid();
  update refkas set ended_at = now() where id = p_id and (a = v_uid or b = v_uid) and ended_at is null;
  if not found then raise exception 'not_found'; end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.chat_list(p_refka uuid, p_after timestamptz default null) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; r refkas; v_out jsonb;
begin
  v_uid := rf_uid();
  r := rf_refka(p_refka);
  select coalesce(jsonb_agg(x.j order by x.at, x.id), '[]'::jsonb) into v_out from (
    select msg.at, msg.id, jsonb_build_object('id', msg.id, 'body', msg.body, 'at', msg.at,
             'mine', msg.from_user = v_uid) as j
    from messages msg
    where msg.refka_id = r.id and (p_after is null or msg.at > p_after)
    order by msg.at desc, msg.id desc limit 200
  ) x;
  if r.a = v_uid then update refkas set a_read_at = clock_timestamp() where id = r.id;
  else update refkas set b_read_at = clock_timestamp() where id = r.id;
  end if;
  return v_out;
end $$;

create or replace function public.chat_send(p_refka uuid, p_body text) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; r refkas; v_body text; msg messages;
begin
  v_uid := rf_uid();
  r := rf_refka(p_refka);
  v_body := btrim(coalesce(p_body, ''), E' \t\r\n');
  if char_length(v_body) not between 1 and 1000 then raise exception 'bad_input'; end if;
  if (select count(*) from messages x where x.from_user = v_uid and x.at > now() - interval '1 minute') >= 30 then
    raise exception 'limit';
  end if;
  insert into messages (refka_id, from_user, body, at) values (r.id, v_uid, v_body, clock_timestamp())
  returning * into msg;
  return jsonb_build_object('id', msg.id, 'at', msg.at);
end $$;

create or replace function public.block_user(p_user uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid;
begin
  v_uid := rf_uid();
  if p_user is null or p_user = v_uid then raise exception 'bad_input'; end if;
  if not exists (select 1 from profiles where user_id = p_user) then raise exception 'not_found'; end if;
  insert into blocks (blocker, blocked) values (v_uid, p_user) on conflict do nothing;
  update refkas set ended_at = now()
  where ended_at is null and a = least(v_uid, p_user) and b = greatest(v_uid, p_user);
  update requests set status = 'cancelled', decided_at = now()
  where status = 'pending'
    and ((from_user = v_uid and to_user = p_user) or (from_user = p_user and to_user = v_uid));
  return jsonb_build_object('ok', true);
end $$;

-- p_reason has a default only because Postgres wants defaults after p_user and p_post; it is required.
create or replace function public.report(p_gym text, p_user uuid default null, p_post uuid default null,
  p_reason text default null) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; m memberships; v_reason text; po posts; v_about uuid;
begin
  m := rf_member(p_gym);
  v_uid := m.user_id;
  v_reason := btrim(coalesce(p_reason, ''), E' \t\r\n');
  if char_length(v_reason) not between 1 and 500 then raise exception 'bad_input'; end if;
  if p_user is null and p_post is null then raise exception 'bad_input'; end if;
  if p_user = v_uid then raise exception 'bad_input'; end if;

  if p_post is not null then
    select * into po from posts where id = p_post and gym_id = m.gym_id;
    -- only a post the reporter can actually see
    if not found or po.by_user = v_uid or po.status <> 'live' or not can_see(v_uid, po.by_user, m.gym_id) then
      raise exception 'not_found';
    end if;
    v_about := po.by_user;
  end if;
  if p_user is not null then
    -- a post report names its author; a different p_user would pin the post on someone else
    if p_post is not null and p_user <> v_about then raise exception 'bad_input'; end if;
    if not exists (select 1 from memberships x where x.gym_id = m.gym_id and x.user_id = p_user) then
      raise exception 'not_found';
    end if;
    v_about := p_user;
  end if;
  if (select count(*) from reports x where x.by_user = v_uid and x.at >= rf_day_start()) >= 10 then
    raise exception 'limit';
  end if;
  insert into reports (gym_id, by_user, about_user, about_post, reason)
  values (m.gym_id, v_uid, v_about, p_post, v_reason);
  return jsonb_build_object('ok', true);
end $$;

-- ================================================================ feed

create or replace function public.feed(p_gym text, p_before timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; m memberships; g gyms;
begin
  m := rf_member(p_gym);
  v_uid := m.user_id;
  select * into g from gyms where id = m.gym_id;
  if coalesce(g.settings ->> 'posts', 'all') = 'off' then return '[]'::jsonb; end if;
  return (
    select coalesce(jsonb_agg(rf_post_json(x, v_uid) order by x.at desc, x.id), '[]'::jsonb) from (
      select po.* from posts po
      where po.gym_id = m.gym_id
        and (p_before is null or po.at < p_before)
        and (po.by_user = v_uid or (po.status = 'live' and can_see(v_uid, po.by_user, po.gym_id)))
      order by po.at desc, po.id limit 20
    ) x);
end $$;

create or replace function public.post_create(p_gym text, p_body text, p_img text default null) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; m memberships; g gyms; v_mode text; v_body text; v_vis text; po posts;
begin
  m := rf_member(p_gym);
  v_uid := m.user_id;
  select * into g from gyms where id = m.gym_id;
  v_mode := coalesce(g.settings ->> 'posts', 'all');
  if v_mode = 'off' then raise exception 'posts_off'; end if;
  v_body := btrim(coalesce(p_body, ''), E' \t\r\n');
  if char_length(v_body) > 500 then raise exception 'bad_input'; end if;
  if p_img is not null and not rf_img_ok(p_img, 205000) then raise exception 'bad_input'; end if;
  if v_body = '' and p_img is null then raise exception 'bad_input'; end if;
  if (select count(*) from posts x where x.by_user = v_uid and x.at >= rf_day_start()) >= 10 then
    raise exception 'limit';
  end if;
  select vis into v_vis from profiles where user_id = v_uid;
  -- approve mode: the owner reviews first, but only posts he is allowed to see (author vis = 'all').
  -- Posts of members with vis 'gender' or 'none' go live for the people who may see them; reports still reach him.
  insert into posts (gym_id, by_user, body, img, status, at)
  values (m.gym_id, v_uid, v_body, p_img,
          case when v_mode = 'approve' and v_vis = 'all' then 'pending' else 'live' end, clock_timestamp())
  returning * into po;
  return jsonb_build_object('post', rf_post_json(po, v_uid));
end $$;

-- toggles; returns the new state in "respected"
create or replace function public.post_respect(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid; po posts; m memberships; v_on boolean;
begin
  v_uid := rf_uid();
  select * into po from posts where id = p_id;
  if not found then raise exception 'not_found'; end if;
  select * into m from memberships where gym_id = po.gym_id and user_id = v_uid;
  if not found or not rf_active(m) then raise exception 'not_found'; end if;   -- do not confirm other gyms' posts
  if po.status <> 'live' or not can_see(v_uid, po.by_user, po.gym_id) then raise exception 'not_found'; end if;
  delete from post_respects where post_id = po.id and user_id = v_uid;
  if found then
    v_on := false;
  else
    insert into post_respects (post_id, user_id) values (po.id, v_uid) on conflict do nothing;
    v_on := true;
  end if;
  return jsonb_build_object('ok', true, 'respected', v_on);
end $$;

create or replace function public.post_delete(p_id uuid) returns jsonb
language plpgsql security definer set search_path = public, extensions, pg_temp as $$
declare v_uid uuid;
begin
  v_uid := rf_uid();
  delete from posts where id = p_id and by_user = v_uid;
  if not found then raise exception 'not_found'; end if;
  return jsonb_build_object('ok', true);
end $$;

-- ==================================================================== 0004_grants.sql
-- Who may call what. Postgres grants EXECUTE to PUBLIC by default and Supabase adds default grants for
-- anon and authenticated, so everything is revoked first and then granted one by one.
--   rf_* helpers, can_see, my_phone : nobody from outside (they run inside the security definer RPCs)
--   any other function in public     : nobody (closed until it is added to a list here)
--   gym_public                       : anon + authenticated
--   every other RPC                  : authenticated only

do $$
declare
  f record;
  v_public text[] := array['gym_public'];
  v_auth text[] := array[
    'owner_create_gym','owner_get_gym','owner_update_gym','owner_upsert_package','owner_delete_package',
    'owner_import_members','owner_go_live','owner_home','owner_members','owner_decide_payment',
    'owner_decide_guest','owner_decide_post','owner_resolve_report','owner_scan','owner_checkin',
    'me','member_join','update_profile','member_home','member_renew','people','request_send',
    'request_respond','request_cancel','requests_list','refkas_list','refka_end','chat_list','chat_send',
    'block_user','report','feed','post_create','post_respect','post_delete'];
begin
  for f in
    select p.oid::regprocedure as sig, p.proname
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind = 'f'      -- every function in public: anything not listed stays closed
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
    if f.proname = any (v_public) then
      execute format('grant execute on function %s to anon, authenticated', f.sig);
    elsif f.proname = any (v_auth) then
      execute format('grant execute on function %s to authenticated', f.sig);
    end if;
  end loop;
end $$;

-- tables stay closed (repeated here on purpose: this file is the last word on access)
revoke all on all tables in schema public from public, anon, authenticated;

-- Supabase gives anon and authenticated EXECUTE on every new function in public by default. Turn that off for
-- functions created later by this role, so a future function is closed until it is added to the lists above.
alter default privileges in schema public revoke execute on functions from public, anon, authenticated;
alter default privileges in schema public revoke all on tables from anon, authenticated;
alter default privileges in schema public revoke all on sequences from anon, authenticated;

commit;
